  /**
   * 
   * @param force means the user explicitly invoked migration
   */
  public synchronized void scheduleMigration(final boolean force) {
    if (force && myMigrationBlock.isMigrationForbiddenWithout(MigrationNotificationsSupport.NOT_DEPLOYED)) {
      myNotifications.showCantStart(myMigrationBlock.getMigrationForbiddenMessage());
      return;
    }

    if (!(force) && isAutoAssistantSuppressed()) {
      postponeWithoutAssistant();
      return;
    }

    final MigrationBlock.BlockCause scheduledBlockCause = new MigrationBlock.BlockCause("migration is already scheduled");
    myMigrationBlock.blockMigrationsCheck(scheduledBlockCause);

    // wait until project is fully loaded (if not yet)
    StartupManager.getInstance(myProject).runWhenProjectIsInitialized(() -> {
      // as we use ui, postpone to EDT
      ApplicationManager.getApplication().invokeLater(() -> {
        try {
          // a check queued before the suppression started (the project-open check) must not show the modal progress and the wizard
          if (!(force) && isAutoAssistantSuppressed()) {
            postponeWithoutAssistant();
            return;
          }
          // a make may have opened its session since this migration was scheduled. Leave without running: the call sets the
          // re-check flag, so the unblock in finally, or the make's sessionClosed() if that comes later, schedules it again
          // as a later non-force check. A user-invoked run (force) gets a balloon saying why; not the modal dialog of the check
          // at the start of scheduleMigration, because a make may be running now and the dialog would stall it
          if (myMigrationBlock.isMigrationForbiddenWithout(scheduledBlockCause, MigrationNotificationsSupport.NOT_DEPLOYED)) {
            if (force) {
              myNotifications.showPostponed(myMigrationBlock.getMigrationForbiddenMessageWithout(scheduledBlockCause, MigrationNotificationsSupport.NOT_DEPLOYED));
            }
            return;
          }
          ProgressManager.getInstance().run(new Task.Modal(myProject, "Synchronizing Files...", false) {
            public void run(@NotNull ProgressIndicator pi) {
              pi.setIndeterminate(true);
              myReloadManager.flush();
              syncRefresh();
            }
          });
          // the modal progress above pumps events, so a make can open its session during it; check again, as above
          if (myMigrationBlock.isMigrationForbiddenWithout(scheduledBlockCause, MigrationNotificationsSupport.NOT_DEPLOYED)) {
            if (force) {
              myNotifications.showPostponed(myMigrationBlock.getMigrationForbiddenMessageWithout(scheduledBlockCause, MigrationNotificationsSupport.NOT_DEPLOYED));
            }
            return;
          }
          final MigrationSetup migrationSetup = myMpsProject.getModelAccess().computeReadAction(() -> new MigrationSetup(myMpsProject));
          // XXX compare to MT.getNewMigrations(). This one is getActualMigrations()
          //     I don't see a point of using PostponedState here, why not MigrationSetup directly? Just for
          //    myPostponedState.set()? 
          PostponedState newState = PostponedState.current(migrationSetup);

          if (myPostponedState.get() == null || force) {
            boolean hasSomethingToApply = newState.hasSomethingToApply();
            if (hasSomethingToApply) {
              Tuples._2<MigrationResult, MigrationError> result = runMigration(migrationSetup);
              if (result._0() == MigrationResult.POSTPONED) {
                myPostponedState.set(newState);
                myNotifications.showRequired(migrationSetup);
              } else if (result._0() == MigrationResult.FINISHED_WITH_ERRORS) {
                ProgressManager.getInstance().run(new Task.Modal(myProject, "Collecting Errors", false) {
                  public void run(@NotNull ProgressIndicator progressIndicator) {
                    // in fact, getProblems doesn't use progress indicator ATM, perhaps, shall drop it altogether?
                    List<IssueKindReportItem> problems = Sequence.fromIterable(result._1().getProblems(progressIndicator)).toList();
                    showProblems(problems);
                  }
                });
                myPostponedState.set(newState);
                myNotifications.showRequired(null);
                cleanup();
              } else if (result._0() == MigrationResult.FINISHED) {
                myPostponedState.set(null);
                cleanup();
              } else {
                throw new IllegalStateException("Unknown result: " + result);
              }
            } else if (force) {
              myNotifications.showNotRequired();
            }
          } else {
            if (myNotifications.showRequired(null)) {
              myPostponedState.accumulateAndGet(newState, new BinaryOperator<PostponedState>() {
                @Override
                public PostponedState apply(PostponedState current, PostponedState additional) {
                  return (current == null ? null : current.add(additional));
                }
              });
            }
          }
        } finally {
          myMigrationBlock.unblockMigrationsCheck(scheduledBlockCause);
        }
      }, ModalityState.nonModal(), myProject.getDisposed());
    });
  }

  /**
   * Until millis from now, a check that finds pending migrations posts the "Migration required"
   * balloon instead of opening the wizard, in every open project. Explicit runs (force) are
   * unaffected. Later calls only extend the deadline, never shorten it.
   */
  public static void suppressAutoAssistantFor(long millis) {
    final long until = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(millis);
    ourAutoAssistantSuppressedUntil.accumulateAndGet(until, (cur, next) -> (((next - cur) > 0) ? next : cur));
  }

  public static boolean isAutoAssistantSuppressed() {
    return ((System.nanoTime() - ourAutoAssistantSuppressedUntil.get()) < 0) || "false".equalsIgnoreCase(System.getProperty(AUTO_ASSISTANT_PROPERTY));
  }

  /**
   * Test hook: forget the deadline.
   */
  public static void clearAutoAssistantSuppression() {
    ourAutoAssistantSuppressedUntil.set(System.nanoTime());
  }

  /**
   * Runs migration (the caller drives MigrationTask) off the EDT, with checks blocked.
   */
  public void runHeadlessMigration(@NotNull Runnable migration) {
    if (!(myHeadlessRunning.compareAndSet(false, true))) {
      throw new IllegalStateException("A headless migration is already running in this project");
    }
    MigrationBlock.BlockCause cause = new MigrationBlock.BlockCause("migration is running headlessly");
    myMigrationBlock.blockMigrationsCheck(cause);
    myMigrationRunning = true;
    try {
      // before the run: a human clicking the balloon's Migrate meanwhile would get the modal
      // "Migration can't start", which stalls every invokeAndWait of the run until it is dismissed
      // under the lock: a postponeWithoutAssistant() that read myHeadlessRunning before it was set has posted its balloon by now
      synchronized (myPostponeLock) {
        myNotifications.expireRequired();
      }
      syncRefresh();
      migration.run();
    } finally {
      try {
        // also after a failed run: partly migrated models must be re-read
        cleanup();
      } finally {
        myPostponedState.set(null);
        // a check queued before the run may have posted a balloon from the half-migrated state
        synchronized (myPostponeLock) {
          myAssistantPostponedState.set(null);
          myNotifications.expireRequired();
        }
        myMigrationRunning = false;
        myHeadlessRunning.set(false);
        // sets myShouldCheckAfterUnblock, so the unblock below re-checks once and re-announces what
        // the run left pending (a balloon while suppressed); no second, racing check
        myMigrationBlock.isMigrationForbidden();
        myMigrationBlock.unblockMigrationsCheck(cause);
      }
    }
  }

  private void postponeWithoutAssistant() {
    final MigrationBlock.BlockCause cause = new MigrationBlock.BlockCause("migration is already scheduled");
    myMigrationBlock.blockMigrationsCheck(cause);
    ApplicationManager.getApplication().executeOnPooledThread(() -> {
      try {
        if (myProject.isDisposed()) {
          return;
        }
        // the scan runs outside myPostponeLock; the lock only orders the balloon against the
        // expireRequired() calls of runHeadlessMigration. Once scheduleMigration decided to postpone,
        // the balloon is posted even if the suppression window lapsed meanwhile: a balloon is never wrong.
        MigrationSetup setup = myMpsProject.getModelAccess().computeReadAction(() -> new MigrationSetup(myMpsProject));
        PostponedState newState = PostponedState.current(setup);
        synchronized (myPostponeLock) {
          // no balloon from a half-migrated state: a headless run, or the wizard a human started meanwhile
          if (myMigrationRunning || myHeadlessRunning.get()) {
            return;
          }
          PostponedState saved = myAssistantPostponedState.get();
          PostponedState added = ((saved == null) ? newState : newState.substract(saved));
          PostponedState humanPostponed = myPostponedState.get();
          if (humanPostponed != null) {
            added = added.substract(humanPostponed);
          }
          if (added.hasSomethingToApply()) {
            myAssistantPostponedState.set(newState);
            myNotifications.showRequired(setup);
          }
        }
      } finally {
        myMigrationBlock.unblockMigrationsCheck(cause);
      }
    });
  }

  /**
   * No idea what does 'Pre-Update Check' mean; assume it's a way to check if project has everything ready prior
   * to updating to a new MPS version.
   */
  public void performProjectPreUpdateCheck(final ProgressMonitor progress) {
    final SRepository repos = myMpsProject.getRepository();
    final List<IssueKindReportItem> problems = ListSequence.fromList(new ArrayList<IssueKindReportItem>());
    repos.getModelAccess().runReadAction(() -> {
      progress.start("Pre-Update Check", 10);
      // we're in model read here, safe to instantiate MigrationSetup
      MigrationSetup migrationSetup = new MigrationSetup(myMpsProject);
      progress.advance(3);

      new MigrationCheckerImpl(myMpsProject).findNotMigrated(progress.subTask(7), migrationSetup.getModuleMigrations(), new Processor<Problem>() {
        public boolean process(Problem p) {
          ListSequence.fromList(problems).addElement(p);
          return ListSequence.fromList(problems).count() < 1000;
        }
      });
    });
    if (ListSequence.fromList(problems).isEmpty()) {
      // I hate this code, but it's too much pain to bother with showProblems() refactoring
      // NON_MODAL here is just because showProblem() uses it
      ApplicationManager.getApplication().invokeLater(() -> myNotifications.showPreUpdateCheckOk(), ModalityState.nonModal());
    } else {
      showProblems(problems);
    }
  }

  private void showProblems(final List<IssueKindReportItem> problems) {
    ApplicationManager.getApplication().invokeLater(() -> {
      // XXX why do we assume myIssueReporter needs RA for *project* repo to show issues?!
      myMpsProject.getRepository().getModelAccess().runReadAction(() -> myIssueReporter.showProblems(problems));
    }, ModalityState.nonModal());
  }

  private enum MigrationResult {
    POSTPONED(),
    FINISHED_WITH_ERRORS(),
    FINISHED()
  }

  private Tuples._2<MigrationResult, MigrationError> runMigration(MigrationSetup migrationSetup) {
    myAssistantPostponedState.set(null);
    myMigrationRunning = true;
    try {
      MigrationSessionImpl session = new MigrationSessionImpl(myMpsProject, migrationSetup);
      final MigrationWizard wizard = new MigrationWizard(myProject, session);
      boolean finished = wizard.showAndGet();
      MigrationError errors = session.getError();
      MigrationResult state;
      if (!(finished) && errors == null) {
        // user has postponed migration
        state = MigrationResult.POSTPONED;
      } else if (errors != null) {
        state = MigrationResult.FINISHED_WITH_ERRORS;
      } else {
        state = MigrationResult.FINISHED;
      }
      return MultiTuple.<MigrationResult,MigrationError>from(state, errors);
    } finally {
      myMigrationRunning = false;
    }
  }

  private void cleanup() {
    SRepository repository = myMpsProject.getRepository();
    repository.getModelAccess().runWriteAction(() -> {
      // here all the models accessible from project's repo should be unloaded
      // repo.getModules() gives all the modules, including deployed.
      for (SModule module : ListSequence.fromList(myMpsProject.getProjectModulesWithGenerators())) {
        for (SModel model : Sequence.fromIterable(module.getModels())) {
          model.unload();
        }
      }
    });
  }

  private void syncRefresh() {
    final Application application = ApplicationManager.getApplication();
    // used to be deprecated WaitForProgressToShow.runOrInvokeAndWaitAboveProgress, replaced with impl
    application.invokeAndWait(application::saveAll);
    VirtualFileUtils.refreshSynchronouslyRecursively(myProject.getBaseDir(), new EmptyProgressMonitor());
    application.invokeAndWait(myReloadManager::flush);
  }

  private void checkNotDeployedLanguages() {
    Set<SLanguage> problems = myNotifications.getNotDeployedUsedLanguages();
    if (SetSequence.fromSet(problems).isEmpty()) {
      myMigrationBlock.ensureUnblocked(MigrationNotificationsSupport.NOT_DEPLOYED);
    } else {
      myMigrationBlock.ensureBlocked(MigrationNotificationsSupport.NOT_DEPLOYED);
    }
  }

  private class MyPropertiesListener implements MigrationProperties.ReloadListener {
    @Override
    public void onReload() {
      checkMigrationNeeded();
    }
  }

  private class MyLangDeployListener implements LanguageRegistryListener {
    @Override
    public void afterLanguagesLoaded(Iterable<LanguageRuntime> loaded) {
      checkNotDeployedLanguages();
      checkMigrationNeededOnLanguageReload(Sequence.fromIterable(loaded).select((this0) -> this0.getIdentity()).toList());
    }

    @Override
    public void beforeLanguagesUnloaded(Iterable<LanguageRuntime> iterable) {
      // languages are still loaded when this notification comes, no way we can notice any change here, therefore we don't
      // check for changed conditions, e.g. with checkNotDeployedLanguages()
    }
  }
